/// <summary>
/// CB233_TOReceiptDetails
/// CB256_PurchaseOrderReceiptDetails
/// The class to create sys operation data contract.
/// </summary>
[DataContract]
public class METSysOperationTaskDataContract implements SysOperationValidatable, SysOperationInitializable
{
    boolean                 isMainBatchTask;
    CreatedTransactionId    createdTransactionId;
    METThreadCount          threadCount;
    METBundleCount          bundleCount;
    
}

Method.Source:
    /// <summary>
    /// Validates the parameters.
    /// </summary>
    /// <returns>Is validated</returns>
    public boolean validate()
    {
        boolean isValid = true;
        
        if (threadCount <= 0)
        {
            isValid = checkFailed("@MET:ThreadCountWarning");
        }

        return isValid;
    }

/// <summary>
/// Initialise global variables
/// </summary>
public void initialize()
{
    isMainBatchTask = true;
}

    /// <summary>
    /// Provides thread count parameter
    /// </summary>
    /// <param name = "_threadCount">Number of sub tasks spawned from main tasks</param>
    /// <returns>The thread count</returns>
    [DataMember, SysOperationControlVisibilityAttribute(true)]
    public METThreadCount parmThreadCount(METThreadCount _threadCount = threadCount)
    {
        threadCount = _threadCount;

        return threadCount;
    }

    /// <summary>
    /// Provides the bundle count parameter
    /// </summary>
    /// <param name = "_bundleCount">Number of records per bundle</param>
    /// <returns>The bundle count</returns>
    [DataMember, SysOperationControlVisibilityAttribute(false)]
    public METBundleCount parmBundleCount(METBundleCount _bundleCount = bundleCount)
    {
        bundleCount = _bundleCount;

        return bundleCount;
    }

    /// <summary>Parm the main task parameter</summary>
    /// <param name = "_isMainBatchTask">The main task value</param>
    /// <returns>The main task value</returns>
    [DataMember, SysOperationControlVisibilityAttribute(false)]
    public Boolean parmIsMainBatchTask(Boolean _isMainBatchTask = isMainBatchTask)
    {
        isMainBatchTask = _isMainBatchTask;

        return isMainBatchTask;
    }
